export const hasPlacePhoto = (placeId: string) => `place:${placeId}` in BY_ART;


/** A real photo for this artwork key, varied by seed; undefined keeps the drawing. */
export const isProductPhoto = (image: ImageRef) => !!BY_ART[image.art]?.[0]?.startsWith('p:');

export function photoFor(image: ImageRef): number | undefined {
  const list = BY_ART[image.art];
  return list ? F[list[image.seed % list.length]] : undefined;
}

